mkdir -p /workspace/project/apps/cinescope/src/app/{movie-list,seat-map,summary,checkout,confirmation} && cd /workspace/project/apps/cinescope/src/app && 
cat > models.ts <<'EOF'
export interface Movie {
  id: number;
  title: string;
  genre: string;
  runtimeMinutes: number;
  format: 'PL dubbing' | 'PL subtitles';
}

export interface Screening {
  id: number;
  movieId: number;
  date: string;
  time: string;
  occupiedSeats: string[];
}

export interface Customer {
  firstName: string;
  lastName: string;
  email: string;
  phone: string;
}

export interface Reservation {
  id?: number;
  screeningId: number;
  seats: string[];
  customer: Customer;
  totalPrice: number;
}

export interface FormValues {
  firstName: string;
  lastName: string;
  email: string;
