187	      .pipe(takeUntilDestroyed(this.destroyRef))
188	      .subscribe({
189	        next: ([movies, screenings]) => {
190	          this.movies.set(movies);
191	          this.screenings.set(screenings);
192	          this.state.set('loaded');
193	        },
